import {openWorkbook,toCol,fromCol,cellAt,curve,analyzeSeries} from './workbook-parser.js';
import {DEFAULT_FORMULA,parseExpression,project,getSummary,csvRows} from './simulation.js';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>typeof n==='number'?new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2}).format(n):String(n??'—');
const short=n=>{if(typeof n!=='number'||!Number.isFinite(n))return'—';const a=Math.abs(n);return a>=1e8?`${fmt(n/1e8)}亿`:a>=1e4?`${fmt(n/1e4)}万`:fmt(n);};
const PRESETS={combo:DEFAULT_FORMULA,scale:'max(0,y*k)',linear:'max(0,y+t*b)',growth:'max(0,y*pow(1+g/100,t))'};
const defaultScenario=()=>({preset:'combo',multiplier:1,delta:0,growth:0,formula:DEFAULT_FORMULA});
let st={list:[],record:null,book:null,data:null,sheet:'',points:[],projected:[],errors:[],summary:null,rawRow:1,rawCol:0,token:0};
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),3800);}
function openDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open('game-balance-lab-workbooks-v1',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('projects'))req.result.createObjectStore('projects',{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function storeOp(type,operation){const db=await openDb();return new Promise((resolve,reject)=>{const tx=db.transaction('projects',type),store=tx.objectStore('projects');const req=operation(store);let res;req.onsuccess=()=>res=req.result;req.onerror=()=>reject(req.error);tx.oncomplete=()=>{db.close();resolve(res);};tx.onerror=()=>{db.close();reject(tx.error);};});}
const listProjects=()=>storeOp('readonly',s=>s.getAll());const save=rec=>storeOp('readwrite',s=>s.put(rec));const remove=id=>storeOp('readwrite',s=>s.delete(id));
const asFile=r=>new File([r.file],r.filename,{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});
function renderList(){const holder=$('projectList');$('projectCount').textContent=st.list.length;holder.innerHTML=st.list.map(r=>`<button class="project-item ${st.record?.id===r.id?'active':''}" data-id="${esc(r.id)}"><strong>▤ ${esc(r.title)}</strong><small>${esc(r.filename)} · ${new Date(r.created).toLocaleDateString('zh-CN')}</small></button>`).join('')||'<div style="font-size:11px;color:#8293b3;padding:14px 5px">还没有项目</div>';}
function setEmpty(show){$('empty').hidden=!show;$('workspace').hidden=show;$('exportConfig').disabled=show;$('topProject').textContent=show?'未选择项目':st.record?.title||'项目';}
async function addProject(file){if(!file)return;toast('正在导入工作簿，文件较大时可能需要一些时间…');try{const wb=await openWorkbook(file);const record={id:`lab-${Date.now()}-${Math.floor(Math.random()*1e6)}`,title:file.name.replace(/\.xlsx$|\.xlsm$/i,''),filename:file.name,created:Date.now(),file:new Blob([file]),bFile:null,watch:[],view:null,model:null,scenario:defaultScenario()};await save(record);st.list=await listProjects();await chooseProject(record.id);toast(`导入成功：${wb.sheets.length} 张工作表`);}catch(err){toast('导入失败：'+err.message);}}
async function chooseProject(id){const r=st.list.find(p=>p.id===id);if(!r)return;const token=++st.token;toast('正在读取项目数值表…');try{const wb=await openWorkbook(asFile(r));if(token!==st.token)return;st.record=r;st.book=wb;st.data=null;st.points=[];st.projected=[];st.errors=[];st.summary=null;setEmpty(false);$('projectName').textContent=r.title;$('projectSubtitle').textContent=`${r.filename} · ${wb.sheets.length} 张工作表 · ${wb.isMacro?'XLSM（不执行宏）':'XLSX'}`;
$('sheetSelect').innerHTML=wb.sheets.map(x=>`<option value="${esc(x.name)}">${esc(x.name)}${x.status==='hidden'?'（隐藏）':''}</option>`).join('');
const preferred=r.model?.sheet||r.view?.sheet||wb.sheets.find(x=>x.status==='visible')?.name||wb.sheets[0]?.name;
restoreScenario();renderList();await chooseSheet(preferred);}
catch(err){toast('打开项目失败：'+err.message);}}
function saveLater(){clearTimeout(saveLater.timer);saveLater.timer=setTimeout(async()=>{if(!st.record)return;try{st.record.model=readMapping();st.record.scenario=readScenario();await save(st.record);}catch(e){toast('保存配置失败：'+e.message);}},500);}
function readMapping(){return {sheet:st.sheet,x:$('xCol').value.trim().toUpperCase(),y:$('yCol').value.trim().toUpperCase(),start:Number($('startRow').value),end:Number($('endRow').value),configured:true};}
function readScenario(){return{preset:$('rulePreset').value,multiplier:Number($('multiplierNumber').value),delta:Number($('deltaNumber').value),growth:Number($('growthNumber').value),formula:$('customFormula').value};}
function restoreScenario(){const s={...defaultScenario(),...(st.record?.scenario||{})};$('rulePreset').value=s.preset in PRESETS||s.preset==='custom'?s.preset:'combo';$('multiplier').value=Math.max(0,Math.min(2.5,s.multiplier));$('multiplierNumber').value=s.multiplier;$('delta').value=Math.max(-500,Math.min(500,s.delta));$('deltaNumber').value=s.delta;$('growth').value=Math.max(-10,Math.min(10,s.growth));$('growthNumber').value=s.growth;$('customFormula').value=s.formula||DEFAULT_FORMULA;updatePresetUi();}
function autoDetect(data,sheet){
  let best=null;for(let xi=0;xi<Math.min(8,data.maxCol);xi++){for(let yi=0;yi<Math.min(22,data.maxCol);yi++){if(xi===yi)continue;const points=curve(data,toCol(xi),toCol(yi),1,Math.min(220,data.maxRow),220);if(points.length<5)continue;let vals=new Set(points.map(p=>p.y)),xvals=new Set(points.map(p=>p.x));let increasing=points.slice(1).filter((p,j)=>p.x>points[j].x).length/Math.max(1,points.length-1);let sc=points.length*.2+Math.min(vals.size,50)*.6+Math.min(xvals.size,50)*.1+increasing*30-(xi>2?12:0);if(!best||sc>best.score)best={x:toCol(xi),y:toCol(yi),start:points[0].row,end:points[points.length-1].row,score:sc};}}
return best||{x:'A',y:'B',start:1,end:100};}
async function chooseSheet(name){if(!name||!st.book)return;const token=++st.token;st.sheet=name;$('sheetSelect').value=name;$('mapPreview').textContent='正在读取工作表…';try{const data=await st.book.load(name);if(token!==st.token)return;st.data=data;const m=st.record.model?.configured&&st.record.model.sheet===name?st.record.model:autoDetect(data,name);$('xCol').value=m.x;$('yCol').value=m.y;$('startRow').value=m.start;$('endRow').value=m.end;st.rawRow=1;st.rawCol=0;refresh();renderRaw();saveLater();}catch(e){toast('读取工作表失败：'+e.message);$('mapPreview').textContent=e.message;}}
function labelOf(col,start){const c=fromCol(col);if(c<0)return '';for(let r=Math.min(12,start-1);r>=1;r--){const value=cellAt(st.data,toCol(c)+r)?.v;if(typeof value==='string'&&value.trim()&&value.length<35&&!/^VIP\d+$/i.test(value.trim()))return value.trim();}return col+' 列';}
function renderColumnHints(){if(!st.data)return;const m=readMapping(),columns=[];for(let i=0;i<Math.min(st.data.maxCol,120);i++){const col=toCol(i),label=labelOf(col,m.start);if(label!==col+' 列'){columns.push({col,label});}}$('columnHints').innerHTML=columns.map(x=>`<option value="${esc(x.col)}" label="${esc(x.label)}"></option>`).join('');
const suggestions=columns.filter(x=>x.col!==m.x).filter(x=>{let hit=0;for(let r=m.start;r<=Math.min(m.start+12,m.end);r++)if(typeof cellAt(st.data,x.col+r)?.v==='number')hit++;return hit>=3;}).slice(0,6);
$('columnSuggestions').innerHTML=suggestions.map(x=>`<button type="button" data-col="${esc(x.col)}" title="推演 ${esc(x.label)}">${esc(x.label)}</button>`).join('');}
function getRowVars(row){const vars={};for(const c of st.data?.byRow.get(row)||[]){if(typeof c.v==='number'&&Number.isFinite(c.v)&&c.col<702)vars[toCol(c.col).toLowerCase()]=c.v;}return vars;}
function errorState(message){$('chart').innerHTML=`<div class="chart-empty">${esc(message)}</div>`;$('mapPreview').innerHTML=`<span style="color:#bd614d">${esc(message)}</span>`;['metricCount','metricBase','metricNext','metricDelta'].forEach(id=>$(id).textContent='—');$('resultsTable').textContent='没有可计算的数据';$('diagnostics').textContent='调整列范围或计算规则后重新模拟。';$('explain').textContent='请检查选取的数据。';$('issueCount').textContent='—';st.projected=[];st.summary=null;}
function refresh(){if(!st.data)return;const m=readMapping();if(fromCol(m.x)<0||fromCol(m.y)<0||m.start<1||m.end<m.start||m.end-m.start>15000)return errorState('请填写有效列号、起止行（最多跨 15000 行）');const points=curve(st.data,m.x,m.y,m.start,m.end,700);st.points=points;if(points.length<2)return errorState('选定列缺少成对数值；请确认横轴、数值列与起止行');renderColumnHints();$('mapPreview').innerHTML=`<strong>${esc(st.sheet)}</strong><div>${esc(m.x)} 列 · ${esc(labelOf(m.x,m.start))} → ${esc(m.y)} 列 · ${esc(labelOf(m.y,m.start))}</div><div>${points.length} 组有效数据 · 首项 ${fmt(points[0].x)} → 末项 ${fmt(points.at(-1).x)}${st.data.truncated?' · 注意：源 Sheet 内容超出读取限制':''}</div>`;
const s=readScenario();let f=s.preset==='custom'?s.formula:PRESETS[s.preset]||DEFAULT_FORMULA;
try{parseExpression(f);const result=project(points,{...s,formula:f},getRowVars);st.projected=result.points;st.errors=result.errors;if(!result.points.length)return errorState('当前规则无法计算有效数据：'+(result.errors[0]?.reason||'未知错误'));st.summary=getSummary(result.points);updateMetrics();renderChart();renderDiagnostics();renderTable();renderExplanation(f);}
catch(e){errorState('推演公式错误：'+e.message);}
}
function updateMetrics(){const s=st.summary;const first=st.projected[0],last=st.projected.at(-1);$('metricCount').textContent=fmt(s.count);$('metricRange').textContent=`${fmt(first.x)} → ${fmt(last.x)}`;$('metricBase').textContent=short(last.base);$('metricNext').textContent=short(last.projected);$('metricDelta').textContent=(s.delta>0?'+':'')+short(s.delta);$('metricDelta').className=s.delta>0?'positive':s.delta<0?'negative':'';$('metricDeltaSub').textContent=s.deltaPercent===null?'原值为 0，无法计算百分比':`${s.deltaPercent>=0?'+':''}${fmt(s.deltaPercent)}% · 相对原始末项`;}
function renderChart(){const arr=[...st.projected].sort((a,b)=>a.x-b.x);const w=920,h=325,p={l:68,r:25,t:20,b:48};let minX=Math.min(...arr.map(v=>v.x)),maxX=Math.max(...arr.map(v=>v.x));let vals=arr.flatMap(v=>[v.base,v.projected]);let minY=Math.min(...vals),maxY=Math.max(...vals);if(minX===maxX)maxX++;if(minY===maxY){minY-=1;maxY+=1;}const margin=(maxY-minY)*.07;minY-=margin;maxY+=margin;
const xx=x=>p.l+(x-minX)/(maxX-minX)*(w-p.l-p.r),yy=y=>h-p.b-(y-minY)/(maxY-minY)*(h-p.t-p.b);let grid='';for(let i=0;i<=4;i++){let y=p.t+(h-p.t-p.b)*i/4;grid+=`<line x1="${p.l}" x2="${w-p.r}" y1="${y}" y2="${y}" stroke="#edf0f6"/><text x="${p.l-12}" y="${y+4}" font-size="11" text-anchor="end" fill="#95a0b4">${esc(short(maxY-(maxY-minY)*i/4))}</text>`;let x=p.l+(w-p.l-p.r)*i/4;grid+=`<text x="${x}" y="${h-15}" font-size="11" text-anchor="middle" fill="#95a0b4">${esc(fmt(minX+(maxX-minX)*i/4))}</text>`;}
const path=key=>arr.map((item,i)=>(i?'L':'M')+xx(item.x).toFixed(2)+','+yy(item[key]).toFixed(2)).join(' ');
$('chartDescription').textContent=`${st.sheet} · ${labelOf($('yCol').value,Number($('startRow').value))} · 横轴 ${labelOf($('xCol').value,Number($('startRow').value))}`;
$('chart').innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Excel 原始数值与假设推演曲线"><defs><linearGradient id="pFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#6b60e8" stop-opacity=".18"/><stop offset="1" stop-color="#6b60e8" stop-opacity="0"/></linearGradient></defs>${grid}<path d="${path('base')}" fill="none" stroke="#aab4ca" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><path d="${path('projected')}" fill="none" stroke="#665ce6" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"/><circle id="hoverBase" cx="-20" cy="-20" r="5" fill="#aab4ca" stroke="white" stroke-width="2"/><circle id="hoverProj" cx="-20" cy="-20" r="5.5" fill="#655be1" stroke="white" stroke-width="2"/><line id="hoverLine" x1="-20" x2="-20" y1="${p.t}" y2="${h-p.b}" stroke="#d6d8e7" stroke-dasharray="4 4"/><rect x="${p.l}" y="${p.t}" width="${w-p.l-p.r}" height="${h-p.t-p.b}" fill="transparent" id="plotOverlay"/></svg>`;
const overlay=$('plotOverlay'),svg=overlay.ownerSVGElement;overlay.addEventListener('pointermove',e=>{const pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const inv=svg.getScreenCTM()?.inverse();if(!inv)return;const at=pt.matrixTransform(inv);const d=arr.reduce((a,b)=>Math.abs(xx(a.x)-at.x)<=Math.abs(xx(b.x)-at.x)?a:b);const x=xx(d.x);$('hoverBase').setAttribute('cx',x);$('hoverBase').setAttribute('cy',yy(d.base));$('hoverProj').setAttribute('cx',x);$('hoverProj').setAttribute('cy',yy(d.projected));$('hoverLine').setAttribute('x1',x);$('hoverLine').setAttribute('x2',x);$('chartHover').textContent=`横轴 ${fmt(d.x)} · 原值 ${fmt(d.base)} · 推演 ${fmt(d.projected)} · 差值 ${d.diff>=0?'+':''}${fmt(d.diff)}`;});}
function renderDiagnostics(){const s=st.summary;const a=analyzeSeries(st.points);const issues=[];if(s.falls)issues.push(`推演后存在 ${s.falls} 次相邻数值下降，需确认是否是刻意设计的节奏。`);if(s.plateaus)issues.push(`推演后有 ${s.plateaus} 次相邻数值持平，可能形成成长平台期。`);if(s.leaps)issues.push(`推演后存在 ${s.leaps} 次明显的数值跃升，建议检查投放节点。`);if(st.errors.length)issues.push(`${st.errors.length} 行未成功计算；例如第 ${st.errors[0].row} 行：${st.errors[0].reason}。`);if(!issues.length)issues.push('当前推演曲线未发现简单的回退、平台期或极端跃升。');$('issueCount').textContent=`${issues.length} 项提示`;$('diagnostics').innerHTML=issues.slice(0,5).map(v=>`<div class="risk-row"><span class="risk-dot">!</span><span>${esc(v)}</span></div>`).join('')+`<p style="font-size:10px;margin-top:10px">原始 Excel：${esc(a.summary)}。算法提示不等同于平衡性结论。</p>`;}
function renderExplanation(formula){const m=readMapping(),s=readScenario();$('explain').innerHTML=`<div><strong>数据来源：</strong>${esc(st.sheet)} 中 ${esc(m.x)} / ${esc(m.y)} 列，行 ${m.start}–${m.end}。</div><div style="margin-top:9px"><strong>调整参数：</strong>倍率 ${fmt(s.multiplier)}×；单位增量 ${fmt(s.delta)}；复合增长 ${fmt(s.growth)}%。</div><div style="margin-top:9px"><strong>使用公式：</strong><code>${esc(formula)}</code></div><div style="margin-top:9px">数值来自 Excel 已保存的结果。仅按上方公式重新计算选定行；没有重算原工作簿内的依赖链、VBA 或外链。</div>`;}
function renderTable(){const pts=st.projected;const step=pts.length>150?Math.ceil(pts.length/150):1;const show=pts.filter((_,i)=>i%step===0||i===pts.length-1);$('resultsTable').innerHTML=`<table><thead><tr><th>Excel 行</th><th>横轴</th><th>原始值</th><th>推演值</th><th>差值</th><th>变化率</th></tr></thead><tbody>${show.map(p=>`<tr><td>${p.row}</td><td>${fmt(p.x)}</td><td>${fmt(p.base)}</td><td>${fmt(p.projected)}</td><td class="${p.diff>=0?'value-up':'value-down'}">${p.diff>0?'+':''}${fmt(p.diff)}</td><td>${p.pct===null?'—':`${p.pct>0?'+':''}${fmt(p.pct)}%`}</td></tr>`).join('')}</tbody></table>`;}
function renderRaw(){if(!st.data||!$('rawDetails').open)return;const data=st.data,row=Math.max(1,st.rawRow),col=Math.max(0,st.rawCol),end=Math.min(row+16,Math.max(data.maxRow,row+16));$('rawStart').value=row;$('rawCol').value=toCol(col);let html='<table><thead><tr><th class="row-number">#</th>';for(let j=0;j<10;j++)html+=`<th>${toCol(col+j)}</th>`;html+='</tr></thead><tbody>';for(let r=row;r<end;r++){html+=`<tr><td class="row-number">${r}</td>`;for(let j=0;j<10;j++){const addr=toCol(col+j)+r,c=cellAt(data,addr);html+=`<td data-addr="${esc(addr)}" title="${esc(addr)}${c?.f?' · 含 Excel 公式':''}">${esc(c?.v??'')}</td>`;}html+='</tr>';}html+='</tbody></table>';$('rawGrid').innerHTML=html;$('rawInfo').textContent=`当前表约 ${fmt(data.cells.size)} 个已读取单元格；预览 ${row}–${end-1} 行`;}
function csvDownload(filename,rows){const str='\ufeff'+rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\r\n');blobDownload(filename,new Blob([str],{type:'text/csv;charset=utf-8'}));}
function blobDownload(name,blob){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1200);}
function updatePresetUi(){const preset=$('rulePreset').value;$('customWrap').hidden=preset!=='custom';const active=preset==='combo'||preset==='custom';[['multiplier',preset==='scale'||active],['delta',preset==='linear'||active],['growth',preset==='growth'||active]].forEach(([key,on])=>{const input=$(key),num=$(key+'Number');input.disabled=!on;num.disabled=!on;});}
function bindParameter(rangeId,numberId){const range=$(rangeId),num=$(numberId);range.addEventListener('input',()=>{num.value=range.value;refresh();saveLater();});num.addEventListener('input',()=>{const v=Number(num.value);if(Number.isFinite(v))range.value=v;refresh();saveLater();});}
function upload(){const input=$('fileInput');input.value='';input.click();}
function wire(){['addProject','headerUpload','emptyUpload'].forEach(id=>$(id).onclick=upload);$('fileInput').addEventListener('change',e=>addProject(e.target.files?.[0]));$('projectList').addEventListener('click',e=>{const b=e.target.closest('[data-id]');if(b)chooseProject(b.dataset.id);});
$('sheetSelect').addEventListener('change',e=>chooseSheet(e.target.value));['xCol','yCol','startRow','endRow'].forEach(id=>$(id).addEventListener('change',()=>{refresh();saveLater();}));
$('columnSuggestions').onclick=e=>{const b=e.target.closest('[data-col]');if(!b)return;$('yCol').value=b.dataset.col;refresh();saveLater();};$('detectColumns').onclick=()=>{if(!st.data)return;const m=autoDetect(st.data,st.sheet);$('xCol').value=m.x;$('yCol').value=m.y;$('startRow').value=m.start;$('endRow').value=m.end;refresh();saveLater();toast(`已推荐 ${m.x} → ${m.y} 列；可手动更改`);};
$('rulePreset').onchange=()=>{updatePresetUi();refresh();saveLater();};bindParameter('multiplier','multiplierNumber');bindParameter('delta','deltaNumber');bindParameter('growth','growthNumber');$('customFormula').addEventListener('input',()=>{refresh();saveLater();});
$('resetScenario').onclick=()=>{st.record.scenario=defaultScenario();restoreScenario();refresh();saveLater();toast('已恢复基准推演参数');};$('applyScenario').onclick=()=>{refresh();saveLater();toast(st.summary?`已计算 ${st.summary.count} 个有效数据点`:'请先检查数据映射与公式');};
$('rawDetails').addEventListener('toggle',renderRaw);$('rawJump').onclick=()=>{const row=Number($('rawStart').value),col=fromCol($('rawCol').value);if(!Number.isInteger(row)||row<1||col<0)return toast('请输入有效单元格起点');st.rawRow=row;st.rawCol=col;renderRaw();};$('rawGrid').onclick=e=>{const el=e.target.closest('[data-addr]');if(!el)return;const c=cellAt(st.data,el.dataset.addr);$('rawSelection').innerHTML=`<b>${esc(st.sheet)}!${esc(el.dataset.addr)}</b> · 缓存结果：${esc(c?.v??'（空）')} ${c?.f?`<div style="margin-top:6px">原 Excel 公式：<code>${esc('='+c.f)}</code></div>`:'<span>（无单元格公式或纯文本）</span>'}`;};
$('exportCsv').onclick=()=>{if(!st.projected.length)return toast('没有可导出的推演数据');csvDownload('GameBalanceLab_数值推演_'+st.sheet+'.csv',csvRows(st.projected));};
$('exportConfig').onclick=()=>{if(!st.record)return;const data={format:'Game Balance Lab V1.5 · projection only',project:st.record.title,originalFile:st.record.filename,sourceMapping:readMapping(),scenario:readScenario(),lastResult:st.summary?{count:st.summary.count,baselineEnd:st.summary.last.base,projectedEnd:st.summary.last.projected,delta:st.summary.delta}:null,notice:'此报告仅记录假设推演，不代表完整 Excel 公式重算。'};blobDownload('GameBalanceLab_'+st.record.title+'_推演方案.json',new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));};
$('renameProject').onclick=async()=>{if(!st.record)return;const value=prompt('项目名称',st.record.title);if(!value?.trim())return;st.record.title=value.trim().slice(0,100);await save(st.record);$('projectName').textContent=st.record.title;$('topProject').textContent=st.record.title;renderList();toast('项目已重命名');};
$('removeProject').onclick=async()=>{if(!st.record)return;if(!confirm(`从当前浏览器移除项目「${st.record.title}」及其文件缓存？不会删除电脑上的原始 Excel。`))return;const id=st.record.id;await remove(id);st.list=await listProjects();st.record=null;st.book=null;st.data=null;setEmpty(true);renderList();if(st.list.length)await chooseProject(st.list[0].id);toast('已移除本地项目');};}
async function boot(){wire();try{st.list=await listProjects();renderList();if(st.list.length)await chooseProject(st.list[0].id);else setEmpty(true);}catch(e){toast('浏览器本地存储不可用：'+e.message);setEmpty(true);}}
boot();
